using System.Text.Json;using JobOrbit.Application.DTOs.AdminJobs;using JobOrbit.Application.DTOs.Jobs;using JobOrbit.Application.Interfaces;using JobOrbit.Domain.Entities;using JobOrbit.Domain.Enums;using Microsoft.EntityFrameworkCore;
namespace JobOrbit.Infrastructure.Persistence.Repositories;public sealed class AdminJobRepository(JobOrbitDbContext db):IAdminJobRepository
{static string?Clean(string?v)=>string.IsNullOrWhiteSpace(v)?null:v.Trim();
public async Task<AdminJobListResult>ListAsync(AdminJobQuery q,CancellationToken t=default){if(q.From>q.To)return new(false,null,"Invalid date range");if(q.OrganizationId.HasValue&&!await db.Organizations.AnyAsync(x=>x.Id==q.OrganizationId,t))return new(false,null,"Organization not found");if(q.DepartmentId.HasValue&&!await db.Departments.AnyAsync(x=>x.Id==q.DepartmentId,t))return new(false,null,"Department not found");if(q.RecruiterId.HasValue&&!await db.RecruiterProfiles.AnyAsync(x=>x.UserId==q.RecruiterId,t))return new(false,null,"Recruiter not found");var rows=db.JobPostings.AsNoTracking();if(!string.IsNullOrWhiteSpace(q.Search)){var s=q.Search.Trim();rows=rows.Where(x=>x.Title.Contains(s)||x.Organization.Name.Contains(s)||x.Department.Name.Contains(s)||(x.RecruiterProfile.User.FirstName+" "+x.RecruiterProfile.User.LastName).Contains(s)||x.Location.Contains(s)||x.JobSkills.Any(j=>j.Skill.Name.Contains(s)));}if(!string.IsNullOrWhiteSpace(q.Status)){if(!Enum.TryParse<JobStatus>(q.Status,true,out var status))return new(false,null,"Invalid job status");rows=rows.Where(x=>x.Status==status);}if(q.OrganizationId.HasValue)rows=rows.Where(x=>x.OrganizationId==q.OrganizationId);if(q.DepartmentId.HasValue)rows=rows.Where(x=>x.DepartmentId==q.DepartmentId);if(q.RecruiterId.HasValue)rows=rows.Where(x=>x.RecruiterProfile.UserId==q.RecruiterId);if(!string.IsNullOrWhiteSpace(q.EmploymentType))rows=rows.Where(x=>x.EmploymentType==q.EmploymentType);if(!string.IsNullOrWhiteSpace(q.WorkplaceType))rows=rows.Where(x=>x.WorkplaceType==q.WorkplaceType);if(q.IsFeatured.HasValue)rows=rows.Where(x=>x.IsFeatured==q.IsFeatured);if(q.From.HasValue)rows=rows.Where(x=>x.CreatedAt>=q.From.Value);if(q.To.HasValue)rows=rows.Where(x=>x.CreatedAt<=q.To.Value);rows=q.Sort.ToLowerInvariant()switch{"oldest"=>rows.OrderBy(x=>x.CreatedAt),"closing"=>rows.OrderBy(x=>x.ClosingAt),"title"=>rows.OrderBy(x=>x.Title),"applications"=>rows.OrderByDescending(x=>x.JobApplications.Count),_=>rows.OrderByDescending(x=>x.CreatedAt)};var total=await rows.CountAsync(t);var items=await rows.Skip((q.Page-1)*q.PageSize).Take(q.PageSize).Select(x=>new AdminJobListItemDto(x.Id,x.Title,x.OrganizationId,x.Organization.Name,x.DepartmentId,x.Department.Name,x.RecruiterProfile.UserId,x.RecruiterProfile.User.FirstName+" "+x.RecruiterProfile.User.LastName,x.Status.ToString(),x.EmploymentType,x.WorkplaceType,x.Location,x.JobApplications.Count,x.IsFeatured,x.PublishedAt,x.ClosingAt,x.CreatedAt)).ToListAsync(t);return new(true,new PagedResultDto<AdminJobListItemDto>{Items=items,Page=q.Page,PageSize=q.PageSize,TotalItems=total,TotalPages=(int)Math.Ceiling(total/(double)q.PageSize)});}
public Task<AdminJobDetailsDto?>DetailsAsync(int id,CancellationToken t=default)=>db.JobPostings.AsNoTracking().Where(x=>x.Id==id).Select(x=>new AdminJobDetailsDto(x.Id,x.Title,x.Description,x.Requirements,x.Responsibilities,x.JobSkills.OrderBy(s=>s.Skill.Name).Select(s=>s.Skill.Name).ToList(),new(x.OrganizationId,x.Organization.Name,x.Organization.Code,x.Organization.IsActive),new(x.DepartmentId,x.Department.Name,x.Department.Code,x.Department.IsActive),new(x.RecruiterProfile.UserId,x.RecruiterProfile.User.FirstName+" "+x.RecruiterProfile.User.LastName,x.RecruiterProfile.User.Email,x.RecruiterProfile.User.IsActive),x.Status.ToString(),x.EmploymentType,x.WorkplaceType,x.Location,x.SalaryMinimum,x.SalaryMaximum,x.Currency,x.ExperienceLevel,x.VacancyCount,x.JobApplications.Count,x.JobApplications.Count(a=>a.Status==ApplicationStatus.Shortlisted),x.JobApplications.SelectMany(a=>a.Interviews).Count(),x.JobApplications.Count(a=>a.Status==ApplicationStatus.Hired),x.IsFeatured,x.PublishedAt,x.ClosingAt,x.CreatedAt,x.UpdatedAt)).SingleOrDefaultAsync(t);
public async Task<AdminJobResult>UpdateAsync(int admin,int id,UpdateAdminJobRequest r,CancellationToken t=default){var job=await db.JobPostings.Include(x=>x.JobSkills).SingleOrDefaultAsync(x=>x.Id==id,t);if(job is null)return new(AdminJobOutcome.NotFound);await using var tx=db.Database.IsRelational()?await db.Database.BeginTransactionAsync(t):null;var names=r.Skills.Select(x=>x.Trim()).Distinct(StringComparer.OrdinalIgnoreCase).ToList();var skills=await db.Skills.Where(x=>names.Contains(x.Name)).ToListAsync(t);foreach(var name in names.Where(n=>skills.All(s=>!s.Name.Equals(n,StringComparison.OrdinalIgnoreCase)))){var skill=new Skill{Name=name};db.Skills.Add(skill);skills.Add(skill);}var old=JsonSerializer.Serialize(new{job.Title,job.Status,job.IsFeatured});job.Title=r.Title.Trim();job.Description=r.Description.Trim();job.Requirements=Clean(r.Requirements);job.Responsibilities=Clean(r.Responsibilities);job.EmploymentType=r.EmploymentType.Trim();job.WorkplaceType=Clean(r.WorkplaceType);job.Location=r.Location.Trim();job.SalaryMinimum=r.SalaryMin;job.SalaryMaximum=r.SalaryMax;job.Currency=r.Currency.Trim().ToUpperInvariant();job.ExperienceLevel=Clean(r.ExperienceLevel);job.VacancyCount=r.VacancyCount;job.ClosingAt=r.ClosingDate?.ToUniversalTime();db.JobSkills.RemoveRange(job.JobSkills);foreach(var skill in skills)job.JobSkills.Add(new JobSkill{Skill=skill,IsRequired=true});db.AuditLogs.Add(new AuditLog{UserId=admin,EntityName=nameof(JobPosting),EntityId=id,Action="AdminUpdateJob",OldValues=old,NewValues=JsonSerializer.Serialize(new{job.Title,job.Status,job.IsFeatured})});await db.SaveChangesAsync(t);if(tx is not null)await tx.CommitAsync(t);return new(AdminJobOutcome.Success,await DetailsAsync(id,t));}
public async Task<AdminJobResult>StatusAsync(int admin,int id,UpdateAdminJobStatusRequest r,CancellationToken t=default){if(!Enum.TryParse<JobStatus>(r.Status,true,out var next))return new(AdminJobOutcome.InvalidStatus);var job=await db.JobPostings.Include(x=>x.Organization).Include(x=>x.Department).Include(x=>x.RecruiterProfile).ThenInclude(x=>x.User).SingleOrDefaultAsync(x=>x.Id==id,t);if(job is null)return new(AdminJobOutcome.NotFound);if(!Allowed(job.Status,next))return new(AdminJobOutcome.InvalidTransition);if(next==JobStatus.Published){if(!job.Organization.IsActive||!job.Department.IsActive||!job.RecruiterProfile.User.IsActive)return new(AdminJobOutcome.InactiveOwnership);if(!job.ClosingAt.HasValue||job.ClosingAt<=DateTime.UtcNow)return new(AdminJobOutcome.Expired);job.PublishedAt??=DateTime.UtcNow;}var old=job.Status;job.Status=next;if(next!=JobStatus.Published)job.IsFeatured=false;db.AuditLogs.Add(new AuditLog{UserId=admin,EntityName=nameof(JobPosting),EntityId=id,Action="AdminChangeJobStatus",OldValues=old.ToString(),NewValues=JsonSerializer.Serialize(new{Status=next.ToString(),Reason=Clean(r.Reason)})});await db.SaveChangesAsync(t);return new(AdminJobOutcome.Success,await DetailsAsync(id,t));}
public async Task<AdminJobResult>FeatureAsync(int admin,int id,UpdateAdminJobFeaturedRequest r,CancellationToken t=default){var job=await db.JobPostings.Include(x=>x.Organization).Include(x=>x.Department).Include(x=>x.RecruiterProfile).ThenInclude(x=>x.User).SingleOrDefaultAsync(x=>x.Id==id,t);if(job is null)return new(AdminJobOutcome.NotFound);if(r.IsFeatured&&(job.Status!=JobStatus.Published||!job.Organization.IsActive||!job.Department.IsActive||!job.RecruiterProfile.User.IsActive||job.ClosingAt<=DateTime.UtcNow))return new(AdminJobOutcome.FeatureRequiresPublished);var old=job.IsFeatured;job.IsFeatured=r.IsFeatured;db.AuditLogs.Add(new AuditLog{UserId=admin,EntityName=nameof(JobPosting),EntityId=id,Action=r.IsFeatured?"AdminFeatureJob":"AdminUnfeatureJob",OldValues=old.ToString(),NewValues=r.IsFeatured.ToString()});await db.SaveChangesAsync(t);return new(AdminJobOutcome.Success,await DetailsAsync(id,t));}
static bool Allowed(JobStatus old,JobStatus next)=>old==next||(old,next)switch{(JobStatus.Draft,JobStatus.Published)=>true,(JobStatus.Published,JobStatus.Paused)=>true,(JobStatus.Published,JobStatus.Closed)=>true,(JobStatus.Paused,JobStatus.Published)=>true,(JobStatus.Paused,JobStatus.Closed)=>true,(JobStatus.Closed,JobStatus.Archived)=>true,_=>false};}
